doc=App.getDocument("hook_lesson5")
for o in doc.Objects:
    print(o.Name,o.TypeId,o.Label)
    for p in o.PropertiesList:
        if p in("ExpressionEngine",):
            print("  expr",o.ExpressionEngine)
    if o.TypeId=="Spreadsheet::Sheet":
        for c in sorted(o.getUsedCells()):
            print("  ",c,o.getContents(c),o.getAlias(c))
    if hasattr(o,"Shape") and o.Shape.Solids:
        print("  vol",o.Shape.Volume,o.Shape.BoundBox,len(o.Shape.Solids),o.Shape.isValid())
    if o.TypeId=="Sketcher::SketchObject":
        print("  placement",o.Placement,o.Support if hasattr(o,'Support') else '')
        for i,g in enumerate(o.Geometry):print("  g",i,g)
        for c in o.Constraints:print("  c",c)
    for p in ("Length","Type","Radius","Size","Reversed","Midplane","Profile","Base","Length2","Offset"):
        if hasattr(o,p) and o.TypeId.startswith("PartDesign"):print("  ",p,getattr(o,p))
    if o.ExpressionEngine: print("  expr",o.ExpressionEngine)
